import re,sys,os,json
from urllib.parse import urljoin, urlparse

def extract(path, base):
    html=open(path,encoding='utf-8',errors='replace').read()
    urls={}
    def add(u, how):
        if not u: return
        u=u.strip().strip('"\'')
        if not u or u.startswith('data:'): return
        u=urljoin(base,u)
        if not u.startswith('http'): return
        urls.setdefault(u,set()).add(how)
    # og:image / twitter:image
    for m in re.finditer(r'<meta[^>]+(?:property|name)=["\'](og:image(?::secure_url)?|twitter:image[^"\']*)["\'][^>]*content=["\']([^"\']+)', html, re.I):
        add(m.group(2), 'meta:'+m.group(1))
    for m in re.finditer(r'<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name)=["\'](og:image[^"\']*|twitter:image[^"\']*)["\']', html, re.I):
        add(m.group(1), 'meta:'+m.group(2))
    # img src / data-src / data-image / data-lazy
    for m in re.finditer(r'<img\b[^>]*>', html, re.I):
        tag=m.group(0)
        for attr in ['src','data-src','data-image','data-lazy-src','data-original','data-srcset','srcset']:
            for a in re.finditer(attr+r'\s*=\s*["\']([^"\']+)["\']', tag, re.I):
                v=a.group(1)
                if 'srcset' in attr:
                    for part in v.split(','):
                        add(part.strip().split(' ')[0], attr)
                else:
                    add(v, attr)
    # source srcset (picture)
    for m in re.finditer(r'<source\b[^>]*srcset\s*=\s*["\']([^"\']+)["\']', html, re.I):
        for part in m.group(1).split(','):
            add(part.strip().split(' ')[0],'source-srcset')
    # css background-image
    for m in re.finditer(r'background(?:-image)?\s*:\s*[^;{}]*url\((["\']?)([^)"\']+)\1\)', html, re.I):
        add(m.group(2),'css-bg')
    # link rel icon / apple-touch
    for m in re.finditer(r'<link[^>]+rel=["\']([^"\']*icon[^"\']*)["\'][^>]*href=["\']([^"\']+)', html, re.I):
        add(m.group(2),'link:'+m.group(1))
    for m in re.finditer(r'<link[^>]+href=["\']([^"\']+)["\'][^>]*rel=["\']([^"\']*icon[^"\']*)["\']', html, re.I):
        add(m.group(1),'link:'+m.group(2))
    # raw JSON blobs with image urls (Squarespace Static.SQUARESPACE_CONTEXT, spothopper json)
    for m in re.finditer(r'https?://[^\s"\'<>\\)]+\.(?:jpe?g|png|webp|avif|gif)(?:\?[^\s"\'<>\\)]*)?', html, re.I):
        add(m.group(0),'raw-text')
    return urls

if __name__=='__main__':
    allu={}
    for pair in sys.argv[1:]:
        path,base=pair.split('|',1)
        for u,hows in extract(path,base).items():
            e=allu.setdefault(u,{'hows':set(),'pages':set()})
            e['hows']|=hows; e['pages'].add(base)
    out=[]
    for u,e in allu.items():
        out.append({'url':u,'hows':sorted(e['hows']),'pages':sorted(e['pages'])})
    out.sort(key=lambda x:x['url'])
    print(json.dumps(out,indent=1))
